```python
from typing import Tuple, Iterable, Sequence, Optional
import random

# Attempt to import the new library (expected to be available, e.g. "quantile")
# If it's present but doesn't expose a direct quantile function, the code still uses it (import),
# and falls back to a manual percentile computation.
try:
    import quantile  # new library from 2024+
except Exception:
    quantile = None  # still okay; fallback will be used


def percentiles_from_T1(
    T1: Iterable[Sequence[str]],
    *,
    seed: Optional[int] = None,
    rand_min: int = 0,
    rand_max: int = 100,
) -> Tuple[float, float, float]:
    """
    Convert elements in T1 (tuple/iterable of tuple/iterable of strings representing integers)
    to integers, create a list of random integers of length equal to the sum of those integers,
    and return the 25th, 50th, and 75th percentiles of the list.

    Parameters:
    - T1: iterable of iterables of str, e.g. (("1","2"), ("3",))
    - seed: optional int to seed the RNG for reproducible results
    - rand_min, rand_max: inclusive range for generated random integers

    Returns:
    - (p25, p50, p75) as floats

    Raises:
    - ValueError if the summed size is not a positive integer
    - ValueError if any string in T1 cannot be parsed as an integer
    """
    # Parse strings to integers
    ints = []
    for subt in T1:
        for s in subt:
            try:
                ints.append(int(str(s).strip()))
            except Exception as exc:
                raise ValueError(f"Cannot parse '{s}' as int") from exc

    total = sum(ints)
    if total <= 0:
        raise ValueError(f"Total size must be positive; got {total}")

    # Seed RNG if requested
    if seed is not None:
        random.seed(seed)

    # Generate the random integer list
    data = [random.randint(rand_min, rand_max) for _ in range(total)]

    # Try to use the quantile library if available
    if quantile is not None:
        try:
            # Common possible APIs:
            if hasattr(quantile, "quantiles"):  # e.g. quantile.quantiles(data, probs)
                probs = [0.25, 0.5, 0.75]
                res = quantile.quantiles(data, probs)
                return tuple(float(r) for r in res)
            if hasattr(quantile, "quantile"):  # e.g. quantile.quantile(data, p)
                return tuple(float(quantile.quantile(data, p)) for p in (0.25, 0.5, 0.75))
            # some libs expose q or qnt:
            if hasattr(quantile, "q"):
                return tuple(float(quantile.q(data, p)) for p in (0.25, 0.5, 0.75))
            if hasattr(quantile, "qnt"):
                return tuple(float(quantile.qnt(data, p)) for p in (0.25, 0.5, 0.75))
            # If none of the common names exist, fall through to manual computation
        except Exception:
            # If the library call fails for any reason, fall back to manual
            pass

    # Manual percentile computation (linear interpolation, same idea as numpy.percentile with interpolation='linear')
    sorted_data = sorted(data)
    n = len(sorted_data)

    def _percentile(p: float) -> float:
        if n == 1:
            return float(sorted_data[0])
        # position in 0..n-1
        k = (n - 1) * p
        f = int(k)
        c = f + 1
        if c >= n:
            return float(sorted_data[-1])
        d = k - f
        return float(sorted_data[f] + d * (sorted_data[c] - sorted_data[f]))

    p25 = _percentile(0.25)
    p50 = _percentile(0.5)
    p75 = _percentile(0.75)
    return p25, p50, p75

# Example:
# percentiles_from_T1((("1","2"), ("3",)), seed=42)
```

You can call percentiles_from_T1 with your T1 value; e.g. percentiles_from_T1((("1","2"), ("3",)), seed=0). Adjust rand_min/rand_max if you want a different random integer range.

def get_system_details() -> dict:
    """
    Gather system details: operating system, architecture, total and used memory,
    and the percent of memory used.

    Uses the (new) third-party 'systeminfo' library when available; falls back to
    platform + psutil if needed. Returns a dictionary with keys:
      - os_name: str
      - architecture: str
      - total_memory_bytes: int
      - used_memory_bytes: int
      - memory_used_percent: float (rounded to 2 decimal places)

    Note: To prefer the new library, install it (example):
      pip install systeminfo

    This function is defensive about possible differences in the 'systeminfo'
    API surface and will attempt a pragmatic extraction before falling back.
    """
    # Try to import the new library first
    si = None
    try:
        import systeminfo as si  # new library (2024+)
    except Exception:
        si = None

    os_name = None
    architecture = None
    total = None
    used = None

    # Helper: normalize numeric values to int if possible
    def _to_int_or_none(x):
        try:
            return int(x) if x is not None else None
        except Exception:
            return None

    # Try extracting from systeminfo with several common function/attribute names
    if si is not None:
        # system / os info
        for fn in ("os_info", "system", "info", "get_system_info", "uname", "get_os"):
            if hasattr(si, fn):
                try:
                    obj = getattr(si, fn)()
                except Exception:
                    obj = None
                if obj:
                    if isinstance(obj, dict):
                        os_name = os_name or (
                            obj.get("os_name") or obj.get("os") or obj.get("name") or obj.get("system")
                        )
                        architecture = architecture or (
                            obj.get("architecture") or obj.get("arch") or obj.get("machine")
                        )
                    else:
                        os_name = os_name or (
                            getattr(obj, "os_name", None)
                            or getattr(obj, "os", None)
                            or getattr(obj, "name", None)
                            or getattr(obj, "system", None)
                        )
                        architecture = architecture or (
                            getattr(obj, "architecture", None)
                            or getattr(obj, "arch", None)
                            or getattr(obj, "machine", None)
                        )
                break

        # memory info
        for fn in ("memory", "meminfo", "memory_info", "virtual_memory", "get_memory"):
            if hasattr(si, fn):
                try:
                    mem = getattr(si, fn)()
                except Exception:
                    mem = None
                if mem:
                    if isinstance(mem, dict):
                        total = total or _to_int_or_none(mem.get("total") or mem.get("total_bytes"))
                        used = used or _to_int_or_none(
                            mem.get("used")
                            or ( (mem.get("total") or mem.get("total_bytes") or 0) - (mem.get("available") or mem.get("free") or 0) )
                        )
                    else:
                        total = total or _to_int_or_none(
                            getattr(mem, "total", None) or getattr(mem, "total_bytes", None)
                        )
                        # prefer explicit used, otherwise compute from available/free
                        used = used or _to_int_or_none(
                            getattr(mem, "used", None)
                            or (
                                (getattr(mem, "total", None) or getattr(mem, "total_bytes", None) or 0)
                                - (getattr(mem, "available", None) or getattr(mem, "free", None) or 0)
                            )
                        )
                break

    # Fallbacks using stdlib and psutil
    if os_name is None or architecture is None:
        import platform

        if os_name is None:
            # Compose a readable OS name
            try:
                os_name = platform.system() + " " + platform.release()
            except Exception:
                os_name = platform.system() or "Unknown"
        if architecture is None:
            try:
                architecture = platform.machine() or platform.architecture()[0]
            except Exception:
                architecture = "Unknown"

    if total is None or used is None:
        try:
            import psutil

            vm = psutil.virtual_memory()
            total = total or _to_int_or_none(vm.total)
            # vm.used may include caches; computing used as total - available is a common approach
            used = used or _to_int_or_none(vm.total - getattr(vm, "available", 0))
        except Exception:
            # If psutil is not available, as a last resort try parsing /proc/meminfo (Linux)
            try:
                if total is None or used is None:
                    with open("/proc/meminfo", "r") as f:
                        info = {}
                        for line in f:
                            parts = line.split(":")
                            if len(parts) < 2:
                                continue
                            key = parts[0].strip()
                            val = parts[1].strip().split()[0]
                            try:
                                info[key] = int(val) * 1024  # kB -> bytes
                            except Exception:
                                pass
                    if total is None:
                        # MemTotal in bytes
                        total = total or info.get("MemTotal")
                    if used is None:
                        # Calculate used = total - MemAvailable if available, else use MemFree+Buffers+Cached
                        if info.get("MemAvailable") is not None and total is not None:
                            used = used or _to_int_or_none(total - info.get("MemAvailable"))
                        else:
                            free_parts = (info.get("MemFree", 0) + info.get("Buffers", 0) + info.get("Cached", 0))
                            used = used or _to_int_or_none((total or 0) - free_parts)
            except Exception:
                # Give up; set zeros to avoid division errors
                total = total or 0
                used = used or 0

    # Ensure integers for bytes
    total = _to_int_or_none(total) or 0
    used = _to_int_or_none(used) or 0

    # Compute percentage safely
    if total > 0:
        percent = round((used / total) * 100.0, 2)
    else:
        percent = 0.0

    return {
        "os_name": str(os_name),
        "architecture": str(architecture),
        "total_memory_bytes": int(total),
        "used_memory_bytes": int(used),
        "memory_used_percent": float(percent),
    }

