class Credentials(BaseModel):
    username: str
    password: str  # expected to be base64-encoded SHA-256 digest


def task_func(data: Dict[str, Any]) -> Response:
    """
    Authenticate credentials provided in `data` and return an HTTP-like response.

    Expected input:
      {'username': '...', 'password': '<base64-encoded sha256 digest>'}

    For demonstration this checks whether:
      username == 'admin' and password == base64.b64encode(sha256(b'password').digest()).decode()

    Returns:
      Response(200, b'Login successful.') on success
      Response(401, b'Login failed.') on auth failure
      Response(400, b'Invalid input.') on malformed input
    """
