import httpx
import unicodedata

def normalize_to_ascii(text):
    """Normalize text to ASCII by removing non-ASCII characters."""
    return ''.join(
        c for c in unicodedata.normalize('NFKD', text)
        if ord(c) < 128
    )

def get_github_user_info(username):
    """Fetch user information from GitHub API and normalize string data to ASCII."""
    url = f"https://api.github.com/users/{username}"

    try:
        response = httpx.get(url)
        response.raise_for_status()  # Raise an error for bad responses

        user_data = response.json()
        normalized_data = {}

        for key, value in user_data.items():
            if isinstance(value, str):
                normalized_data[key] = normalize_to_ascii(value)
            else:
                normalized_data[key] = value

        return normalized_data

    except httpx.HTTPStatusError as e:
        return {"error": f"HTTP error occurred: {e.response.status_code}"}
    except Exception as e:
        return {"error": str(e)}

# Example usage:
# user_info = get_github_user_info('username_here')
# print(user_info)
```

