def median_nested(L):
    """
    Compute the median of all numeric elements in a nested list/iterable L using Polars.

    - Flattens arbitrarily nested lists/tuples/sets/generators (string/bytes are treated as scalar).
    - Ignores None values.
    - Raises ValueError if no numeric elements are found.
    - Raises TypeError if any non-numeric (non-coercible) element is encountered.

    Returns a float median.
    """
    import polars as pl

    def _flatten(obj):
        # Recursively yield scalar items from nested iterables (but treat str/bytes as scalar)
        if obj is None:
            return
        if isinstance(obj, (list, tuple, set, frozenset)):
            for x in obj:
                yield from _flatten(x)
        elif hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes, dict)):
            # covers generators and other iterables (except dict; dict would be treated as scalar)
            try:
                for x in obj:
                    yield from _flatten(x)
            except TypeError:
                # not actually iterable -> treat as scalar
                yield obj
        else:
            yield obj

    values = list(_flatten(L))
    # remove None
    values = [v for v in values if v is not None]

    if not values:
        raise ValueError("No (non-None) elements found to compute median.")

    # Try direct cast via Polars (preferred for performance)
    try:
        series = pl.Series(values).cast(pl.Float64)
        # If cast produced all nulls, fall back to checking elements
        if series.null_count() == len(series):
            raise pl.ComputeError()
    except Exception:
        # Try coercing item-by-item to float and raise informative error on failure
        coerced = []
        for v in values:
            try:
                coerced.append(float(v))
            except Exception:
                raise TypeError(f"Non-numeric element encountered and cannot be coerced to float: {v!r}")
        series = pl.Series(coerced)

    med = series.median()
    if med is None:
        raise ValueError("Median could not be computed (no valid numeric elements).")
    return float(med)

# Example usage:
# print(median_nested([1, [2, [3, 4]], (5,), {6, 7}, None]))  # -> 4.0
