Below is a single, self-contained Python function that opens an image file, runs OCR (preferring python-doctr when available, and falling back to pytesseract), then converts the extracted text into a requested target encoding. If OCR yields no usable text, it falls back to extracting textual comments/metadata embedded in the image (EXIF user comment, PNG tEXt chunks, JPEG comment, etc.). The function will attempt to detect original byte encodings when possible (using charset_normalizer or chardet if available) and will produce safe output even if detection is not available.

Notes:
- Preferred OCR backend: python-doctr (modern OCR library). If doctr is not installed, the function will try pytesseract. You can install doctr via pip (if needed).
- For best OCR with pytesseract, ensure Tesseract is installed on the system.
- Optional encoder detectors: charset_normalizer or chardet (if available) will be used to best detect original comment encodings.

Usage:
- ocr_and_convert("image.jpg", target_encoding="utf-8")
- Returns a dict with keys: text (unicode string), bytes (encoded bytes in target encoding), target_encoding, source_backend, fallback_used (True/False), detected_original_encoding (or None).

Code:

```python
def ocr_and_convert(image_path, target_encoding="utf-8", doctr_prefer=True, pytesseract_lang=None):
    """
    Open an image file, extract text using OCR, convert the text to target encoding,
    with a fallback to reading image comments/metadata when OCR yields nothing.

    Parameters:
    - image_path (str): Path to the image file.
    - target_encoding (str): Target encoding name, e.g., 'utf-8', 'latin-1', 'utf-16'.
    - doctr_prefer (bool): If True, try python-doctr first (if installed). If False, try pytesseract first.
    - pytesseract_lang (str or None): lang list for pytesseract like 'eng' or 'eng+fra'. None = default.

    Returns:
    dict with keys:
      - text (str): extracted text (unicode).
      - bytes (bytes): the text encoded in target_encoding (errors='replace' used).
      - target_encoding (str)
      - source_backend (str): 'doctr', 'pytesseract', or 'image_comment'
      - fallback_used (bool): True if we used the image comment fallback
      - detected_original_encoding (str or None): best-effort detected encoding of original bytes (for comments)
      - errors (list): any error messages encountered during processing

    Dependencies (optional):
    - python-doctr (preferred OCR backend)
    - pytesseract (fallback OCR)
    - pillow (PIL) (required to open images)
    - charset_normalizer or chardet (optional, for encoding detection)
    """

    from PIL import Image, PngImagePlugin, JpegImagePlugin, ExifTags
    import io, sys

    errors = []
    extracted_text = ""
    source_backend = None
    fallback_used = False
    detected_enc = None

    # Helper: try to detect encoding of bytes using either charset_normalizer or chardet
    def detect_encoding_guess(b):
        try:
            # try charset_normalizer first (modern)
            import charset_normalizer as cn
            try:
                res = cn.from_bytes(b)
                if res and len(res) > 0:
                    best = res.best()
                    if best:
                        return best.encoding
            except Exception:
                pass
        except Exception:
            pass
        try:
            import chardet
            out = chardet.detect(b)
            return out.get("encoding")
        except Exception:
            return None

    # 1) Open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise RuntimeError(f"Cannot open image {image_path!r}: {e}")

    # Internal helper to try doctr OCR
    def try_doctr(img_path):
        try:
            # import lazily to avoid hard dependency
            from doctr.io import DocumentFile
            from doctr.models import ocr_predictor
        except Exception as e:
            raise RuntimeError(f"doctr import failed: {e}")

        try:
            model = ocr_predictor(pretrained=True)  # download pretrained weights on first run
            # DocumentFile.from_images accepts path(s)
            doc = model(DocumentFile.from_images(img_path))
            # extract text in a resilient way
            text_parts = []
            # doctr's Document has export() in typical versions; try that first
            if hasattr(doc, "export"):
                try:
                    exported = doc.export()
                    for page in exported.get("pages", []):
                        for block in page.get("blocks", []):
                            for line in block.get("lines", []):
                                v = line.get("value") or line.get("text") or ""
                                if v:
                                    text_parts.append(v)
                except Exception:
                    # fallback to attribute traversal
                    pass
            if not text_parts:
                # attribute-traverse fallback
                try:
                    pages = getattr(doc, "pages", [])
                    for page in pages:
                        blocks = getattr(page, "blocks", [])
                        for block in blocks:
                            lines = getattr(block, "lines", [])
                            for line in lines:
                                v = getattr(line, "value", None) or getattr(line, "text", None) or ""
                                if v:
                                    text_parts.append(v)
                except Exception:
                    pass
            return "\n".join(text_parts).strip()
        except Exception as e:
            raise RuntimeError(f"doctr OCR failed: {e}")

    # Internal helper to try pytesseract OCR
    def try_pytesseract(img_obj, lang=None):
        try:
            import pytesseract
        except Exception as e:
            raise RuntimeError(f"pytesseract import failed: {e}")
        try:
            if lang:
                txt = pytesseract.image_to_string(img_obj, lang=lang)
            else:
                txt = pytesseract.image_to_string(img_obj)
            return txt.strip()
        except Exception as e:
            raise RuntimeError(f"pytesseract OCR failed: {e}")

    # Internal helper to extract image comments/metadata
    def extract_image_comment(img_obj):
        parts = []
        # PIL image.info often has 'comment' or PNG text entries
        info = getattr(img_obj, "info", {}) or {}
        # PNG tEXt keys are in info as strings
        for k, v in info.items():
            if k and k.lower() in ("comment", "description", "title", "text", "xml:com"):
                if isinstance(v, bytes):
                    parts.append(v)
                else:
                    try:
                        parts.append(str(v))
                    except Exception:
                        parts.append(repr(v))
        # EXIF tags
        try:
            exif = img_obj.getexif()
            if exif and len(exif):
                # map tag codes to names
                tagmap = {v: k for k, v in ExifTags.TAGS.items()}
                for tag_id, val in exif.items():
                    name = ExifTags.TAGS.get(tag_id, tag_id)
                    if name in ("UserComment", "ImageDescription", "XPComment", "Comment"):
                        parts.append(val)
        except Exception:
            pass

        # JPEG comment (Pillow stores JPEG comment under info.get('comment'))
        if isinstance(info.get("comment"), (bytes, str)):
            parts.append(info.get("comment"))

        # ensure we have byte-chunks separated
        combined_bytes = b""
        combined_texts = []
        for p in parts:
            if isinstance(p, bytes):
                combined_bytes += p + b"\n"
            else:
                try:
                    # normal str
                    combined_texts.append(p)
                except Exception:
                    combined_texts.append(str(p))
        # If we have bytes, try to decode them (detect encoding)
        if combined_bytes:
            guess = detect_encoding_guess(combined_bytes)
            decoded = None
            if guess:
                try:
                    decoded = combined_bytes.decode(guess, errors="replace")
                except Exception:
                    decoded = combined_bytes.decode("utf-8", errors="replace")
            else:
                try:
                    decoded = combined_bytes.decode("utf-8", errors="replace")
                except Exception:
                    decoded = combined_bytes.decode("latin-1", errors="replace")
            return decoded, guess
        # else return joined texts
        if combined_texts:
            return "\n".join(combined_texts), None
        return "", None

    # Try OCR in preferred order
    ocr_attempts = []
    if doctr_prefer:
        ocr_attempts = ["doctr", "pytesseract"]
    else:
        ocr_attempts = ["pytesseract", "doctr"]

    ocr_success = False
    for backend in ocr_attempts:
        if backend == "doctr":
            try:
                text = try_doctr(image_path)
                if text:
                    extracted_text = text
                    source_backend = "doctr"
                    ocr_success = True
                    break
            except Exception as e:
                errors.append(str(e))
                # continue to next backend
        elif backend == "pytesseract":
            try:
                text = try_pytesseract(img, lang=pytesseract_lang)
                if text:
                    extracted_text = text
                    source_backend = "pytesseract"
                    ocr_success = True
                    break
            except Exception as e:
                errors.append(str(e))
                # continue

    # If OCR didn't produce usable text, try fallback to image comments/metadata
    if not ocr_success:
        fallback_used = True
        comment_text, detected_enc = extract_image_comment(img)
        if comment_text:
            extracted_text = comment_text
            source_backend = "image_comment"
            detected_enc = detected_enc
        else:
            extracted_text = ""
            source_backend = source_backend or "none"

    # Now we have extracted_text as a Python str (most common)
    # However, if extracted_text is bytes (unlikely here), handle that
    if isinstance(extracted_text, bytes):
        # detect original encoding
        detected = detect_encoding_guess(extracted_text)
        if detected:
            try:
                extracted_text = extracted_text.decode(detected, errors="replace")
                detected_enc = detected
            except Exception:
                extracted_text = extracted_text.decode("utf-8", errors="replace")
                detected_enc = detected or "utf-8"
        else:
            try:
                extracted_text = extracted_text.decode("utf-8", errors="replace")
                detected_enc = "utf-8"
            except Exception:
                extracted_text = extracted_text.decode("latin-1", errors="replace")
                detected_enc = "latin-1"

    # Ensure we have a string
    if not isinstance(extracted_text, str):
        try:
            extracted_text = str(extracted_text)
        except Exception:
            extracted_text = ""

    # Convert to target encoding bytes
    try:
        encoded_bytes = extracted_text.encode(target_encoding, errors="replace")
    except Exception as e:
        errors.append(f"Encoding to target {target_encoding} failed: {e}")
        # fallback: use utf-8 bytes
        encoded_bytes = extracted_text.encode("utf-8", errors="replace")
        target_encoding = "utf-8"

    return {
        "text": extracted_text,
        "bytes": encoded_bytes,
        "target_encoding": target_encoding,
        "source_backend": source_backend,
        "fallback_used": fallback_used,
        "detected_original_encoding": detected_enc,
        "errors": errors,
    }
